use verus::prelude::*;

verus! {

    /// Given a vector `l` of non‐empty `Vec<char>`, return a new `Vec<char>` of the same length
    /// where the i-th character is the last character of the i-th inner vector of `l`.
    pub fn extract_rear_chars(l: &Vec<Vec<char>>) -> Vec<char>
        // every inner vector is non‐empty
        requires(forall(|i: usize| i < l.len() ==> l[i].len() > 0))
        // output length matches input length, and each character is the last of the corresponding inner vector
        ensures(|res: Vec<char>| 
            res.len() == l.len() &&
            forall(|i: usize| i < l.len() ==> res[i] == l[i][l[i].len() - 1])
        )
    {
        let mut res: Vec<char> = Vec::new();
        let mut i: usize = 0;

        // iterate over each inner vector
        while i < l.len() {
            // loop invariants
            invariant(i <= l.len());
            invariant(res.len() == i);
            invariant(forall(|j: usize| 
                j < i ==> res[j] == l[j][l[j].len() - 1]
            ));
            decreases(l.len() - i);

            // extract the last character of l[i] and push onto res
            let inner: &Vec<char> = &l[i];
            let last_char: char = inner[inner.len() - 1];
            res.push(last_char);

            i += 1;
        }

        res
    }

}